input.new_string:
module pcb_card_slots() {
    // 槽从内腔面往壁内切（第二轮 #13：起点必须是内腔面，不能留 0.2 薄壁）
    // 左壁（X=dx 面）
    translate([dx - slot_d, dy - 0.5, dz + slot_zc - slot_w/2])
        cube([slot_d + 0.1, pcb_l + 1.0, slot_w]);
    // 右侧：X=pcb_w 处无实体壁（右侧是 W5500 区），模块平台兼作限位，不切槽
    // 下壁（Y=dy 面）
    translate([dx - 0.5, dy - slot_d, dz + slot_zc - slot_w/2])
        cube([pcb_w + 1.0, slot_d + 0.1, slot_w]);
    // 上壁（Y=dy+pcb_l 面）
    translate([dx - 0.5, dy + pcb_l, dz + slot_zc - slot_w/2])
        cube([pcb_w + 1.0, slot_d + 0.1, slot_w]);
}

input.old_string:
module pcb_card_slots() {
    // 槽深 slot_d，槽宽 slot_w，中心 Z=slot_zc
    // 左壁（X=0）
    translate([-0.1, dy - 0.5, dz + slot_zc - slot_w/2])
        cube([slot_d + 0.1, pcb_l + 1.0, slot_w]);
    // 右侧：在 X=pcb_w 处做导轨（右侧是 W5500 区，无实体壁）
    translate([dx + pcb_w - slot_d, dy - 0.5, dz + slot_zc - slot_w/2])
        cube([slot_d + 0.1, pcb_l + 1.0, slot_w]);
    // 下壁（Y=0）
    translate([dx - 0.5, -0.1, dz + slot_zc - slot_w/2])
        cube([pcb_w + 1.0, slot_d + 0.1, slot_w]);
    // 上壁（Y=cavity_y）
    translate([dx - 0.5, dy + pcb_l - slot_d, dz + slot_zc - slot_w/2])
        cube([pcb_w + 1.0, slot_d + 0.1, slot_w]);
}

