/* ============================================================ */
/* W5500 模块 M3 锁固矮柱 [H]                                     */
/* 柱只到模块底面（4mm 高），不全高、不进内腔；                     */
/* 左孔 x=90.4 在平台左侧，用 6mm 宽桥臂从平台搭过去                */
/* ============================================================ */
module w5500_mount_bosses() {
    for (h = mod_holes) {
        hx = dx + h[0]; hy = dy + h[1];
        if (h[0] >= plat_x0) {
            // 右孔：直接立在平台上
            translate([hx, hy, dz + plat_h])
                difference() {
                    cylinder(d=mod_boss_d, h=mod_boss_h, $fn=24);
                    translate([0, 0, -0.1])
                        cylinder(d=mod_screw_d, h=mod_boss_h + 0.2, $fn=16);
                }
        } else {
            // 左孔：桥臂从平台左缘搭到孔位，末端立矮柱
            // 桥臂在平台顶面高度，宽 6mm（沿 Y），厚 mod_boss_h
            translate([hx, hy - 3, dz + plat_h])
                cube([plat_x0 + dx - hx + 0.1, 6.0, mod_boss_h]);
            translate([hx, hy, dz + plat_h])
                difference() {
                    cylinder(d=mod_boss_d, h=mod_boss_h, $fn=24);
                    translate([0, 0, -0.1])
                        cylinder(d=mod_screw_d, h=mod_boss_h + 0.2, $fn=16);
                }
        }
    }
}

