/* ============================================================ */
module oled_seat() {
    // rbox 从 (0,0) 铺到 (w,l)，必须减去半宽半高才居中
    oled_outer = oled_mod + 2*oled_clr + 2*oled_wall;
    oled_inner = oled_mod + 2*oled_clr;
    translate([dx + h1[0] - oled_outer/2, dy + h1[1] - oled_outer/2, -oled_seat_h])
